// Valida lo que manda el modelo y calcula la ventana en la que un evento
// existente impediria agendar esta cita.
//
// Regla del negocio (2026-08-13): una sola persona atiende, asi que no puede
// haber citas en paralelo. La cita ocupa [hora, hora+duracion] y ademas exige
// su colchon a cada lado, asi que cualquier evento que toque
// [hora-colchon, hora+duracion+colchon] es un choque.
//
// Duracion y colchon por tipo (2026-08-25): una llamada es mas corta y necesita
// menos aire que recibir a alguien en la sede, asi que va de 20 con 20 de
// colchon. El resto sigue en 30 y 30.
const MINUTOS = {
  visita_sede:  { duracion: 30, colchon: 30 },
  prueba_traje: { duracion: 30, colchon: 30 },
  llamada:      { duracion: 20, colchon: 20 },
  asesoria:     { duracion: 30, colchon: 30 },
};
const ZONA = 'America/Bogota';
const TIPOS = Object.keys(MINUTOS);

// Horario de atencion (2026-08-19). Clave = dia de la semana de Luxon:
// 1=lunes ... 6=sabado, 7=domingo.
const HORARIO = {
  1: ['10:00', '19:00'],
  2: ['10:00', '19:00'],
  3: ['10:00', '19:00'],
  4: ['10:00', '19:00'],
  5: ['10:00', '19:00'],
  6: ['10:00', '18:30'],
  7: ['10:30', '13:00'],
};

const entrada = $input.first().json;
const texto = (v) => (v ?? '').toString().trim();

const tipo_cita = texto(entrada.tipo_cita);
const fecha = texto(entrada.fecha);
const hora = texto(entrada.hora);
const detalle = texto(entrada.detalle);
const telefono = texto(entrada.telefono);
const nombre = texto(entrada.nombre);
const telefono_contacto = texto(entrada.telefono_contacto);
// Solo digitos: sirve para validar y para marcar.
const digitos = telefono_contacto.replace(/\D/g, '');

// El mensaje va de vuelta al agente, no al cliente: se redacta como
// instruccion para que sepa que corregir y vuelva a llamar la herramienta.
const rechazar = (mensaje) => [{ json: { valido: false, agendada: false, mensaje } }];

if (!TIPOS.includes(tipo_cita)) {
  return rechazar(`tipo_cita invalido: "${tipo_cita}". Debe ser exactamente uno de: ${TIPOS.join(', ')}.`);
}

if (!nombre) {
  return rechazar('Falta el nombre del cliente. Preguntaselo antes de agendar la cita.');
}

// Seguro despues de validar el tipo: aca ya se sabe que existe en MINUTOS.
const { duracion: DURACION_MIN, colchon: COLCHON_MIN } = MINUTOS[tipo_cita];

// El telefono con el que escribe NO sirve para llamar: cuando el cliente tiene
// el numero oculto llega como JID (@lid) o como userId, que no se puede marcar.
// Por eso el numero de contacto se pide siempre, y en las llamadas es critico.
if (digitos.length < 7) {
  return rechazar(
    tipo_cita === 'llamada'
      ? 'Falta el numero al que hay que llamar. Pideselo al cliente antes de agendar la llamada: "confirmame por fa a que numero te llamo".'
      : 'Falta el numero de contacto del cliente. Pideselo antes de agendar: "por fa me confirmas un numero de contacto".'
  );
}

// Formato estricto a proposito: si el modelo manda "manana" o "3pm" hay que
// devolverselo como error, no dejar que Google reciba una fecha inventada.
const inicio = DateTime.fromFormat(`${fecha} ${hora}`, 'yyyy-MM-dd HH:mm', { zone: ZONA });

if (!inicio.isValid) {
  return rechazar(`Fecha u hora invalidas: "${fecha} ${hora}". Usa fecha en formato YYYY-MM-DD y hora en formato HH:MM de 24 horas.`);
}

if (inicio < DateTime.now().setZone(ZONA)) {
  return rechazar(`Ese horario ya paso (${inicio.toFormat('dd/MM/yyyy HH:mm')}). Proponle al cliente una fecha y hora futuras.`);
}

const fin = inicio.plus({ minutes: DURACION_MIN });

// La cita COMPLETA debe caber en la franja: se valida el fin, no solo el
// inicio. Si no, una cita de 30 min a las 18:45 el sabado terminaria a las
// 19:15, con el local ya cerrado.
const [abre, cierra] = HORARIO[inicio.weekday];
// sabado -> sabados, domingo -> domingos; lunes..viernes ya son invariables.
const diaBase = inicio.setLocale('es').toFormat('cccc');
const dia = diaBase.endsWith('s') ? diaBase : `${diaBase}s`;
const apertura = DateTime.fromFormat(`${inicio.toFormat('yyyy-MM-dd')} ${abre}`, 'yyyy-MM-dd HH:mm', { zone: ZONA });
const cierreDt = DateTime.fromFormat(`${inicio.toFormat('yyyy-MM-dd')} ${cierra}`, 'yyyy-MM-dd HH:mm', { zone: ZONA });

if (inicio < apertura || fin > cierreDt) {
  const ultima = cierreDt.minus({ minutes: DURACION_MIN }).toFormat('HH:mm');
  return rechazar(`Fuera del horario de atencion. Los ${dia} atendemos de ${abre} a ${cierra}, y como cada cita dura ${DURACION_MIN} minutos la ultima puede empezar a las ${ultima}. Proponle al cliente otra hora dentro de esa franja.`);
}

return [{
  json: {
    valido: true,
    tipo_cita,
    detalle,
    telefono,
    telefono_contacto,
    nombre,
    inicio: inicio.toISO(),
    fin: fin.toISO(),
    ventana_inicio: inicio.minus({ minutes: COLCHON_MIN }).toISO(),
    ventana_fin: fin.plus({ minutes: COLCHON_MIN }).toISO(),
    inicio_legible: inicio.setLocale('es').toFormat("cccc d 'de' LLLL 'a las' HH:mm"),
    duracion_min: DURACION_MIN,
    colchon_min: COLCHON_MIN,
  },
}];

